import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Configuration","description":"Three YAML files in one directory: config.yaml, admin.yaml, client.yaml. Env prefixes KIRIVERS_ / KIRIVERS_ADMIN_ / KIRIVERS_CLIENT_.","frontmatter":{"title":"Configuration","description":"Three YAML files in one directory: config.yaml, admin.yaml, client.yaml. Env prefixes KIRIVERS_ / KIRIVERS_ADMIN_ / KIRIVERS_CLIENT_."},"headers":[],"relativePath":"en/guide/config/index.md","filePath":"en/guide/config/index.md","lastUpdated":1790057721000}`),a={name:`en/guide/config/index.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>Keep three files in <strong>one folder</strong>:</p><div class="language-text line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>config-dir/</span></span>
<span class="line"><span>  config.yaml     # system: database, storage, cache, jobs, security</span></span>
<span class="line"><span>  admin.yaml      # admin plane: addr, TLS, trusted_proxies, static_dir</span></span>
<span class="line"><span>  client.yaml     # client plane: addr, TLS, trusted_proxies</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>-config</code> points at that directory or the system file. Missing files load sibling <code>*-example.yaml</code>.</p><table tabindex="0"><thead><tr><th>File</th><th>Env prefix</th><th>Example</th></tr></thead><tbody><tr><td><code>config.yaml</code></td><td><code>KIRIVERS_</code></td><td><code>postgres.dsn</code> → <code>KIRIVERS_POSTGRES_DSN</code></td></tr><tr><td><code>admin.yaml</code></td><td><code>KIRIVERS_ADMIN_</code></td><td><code>addr</code> → <code>KIRIVERS_ADMIN_ADDR</code></td></tr><tr><td><code>client.yaml</code></td><td><code>KIRIVERS_CLIENT_</code></td><td><code>addr</code> → <code>KIRIVERS_CLIENT_ADDR</code></td></tr></tbody></table><p><code>trusted_proxies</code> and <code>static_dir</code> are <strong>not</strong> in <code>config.yaml</code>. They belong to the plane YAML files.</p><p>If either plane sets <code>mode=debug</code>, the whole process uses Gin debug mode; otherwise release.</p><h2 id="logging" tabindex="-1">Logging <a class="header-anchor" href="#logging" aria-label="Permalink to “Logging”">​</a></h2><p>One process system stream plus system+access on each plane (five streams). Each stream must enable console or rolling file (or both). If both sinks are off, startup fails and the process does not listen.</p><p>Use environment variables to inject secrets. Treat the three YAML files as the operator-facing source. Child pages:</p><ul><li><a href="./bootstrap-admin">Bootstrap admin</a></li><li><a href="./client.yaml">client.yaml</a></li><li><a href="./config.yaml">config.yaml</a></li><li><a href="./cache">Cache</a></li><li><a href="./s3">S3</a></li><li><a href="./local-storage">Local disk</a></li><li><a href="./admin.yaml">admin.yaml</a></li><li><a href="./reverse-proxy">Reverse proxy</a></li><li><a href="./cluster">Cluster YAML</a></li><li><a href="./security">Security</a></li></ul>`,11)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};